import{_ as a,o as e,c as t,a3 as l}from"./chunks/framework.DACwFHq9.js";const k=JSON.parse('{"title":"Sidecar Plugin API v3 发布收口计划","description":"","frontmatter":{},"headers":[],"relativePath":"Plan/sidecar-plugin-api-v3-migration.md","filePath":"Plan/sidecar-plugin-api-v3-migration.md","lastUpdated":1785283012000}'),s={name:"Plan/sidecar-plugin-api-v3-migration.md"};function d(n,i,r,o,h,c){return e(),t("div",null,[...i[0]||(i[0]=[l(`<h1 id="sidecar-plugin-api-v3-发布收口计划" tabindex="-1">Sidecar Plugin API v3 发布收口计划 <a class="header-anchor" href="#sidecar-plugin-api-v3-发布收口计划" aria-label="Permalink to &quot;Sidecar Plugin API v3 发布收口计划&quot;">​</a></h1><blockquote><p>状态：主体实施与 review 修复已完成；开发模式已验证 API v3 和分批优化，待发布候选主应用与插件联合验收</p><p>最近更新：2026-07-28</p><p>首个迁移插件：<code>paddle-ocr</code> 0.8.0</p></blockquote><h2 id="_1-兼容边界" tabindex="-1">1. 兼容边界 <a class="header-anchor" href="#_1-兼容边界" aria-label="Permalink to &quot;1. 兼容边界&quot;">​</a></h2><p>API v3 为长任务提供显式作业协议，不为 Paddle OCR 0.8.0 保留 v2 OCR 调用回退；新主程序仍可加载既有 API v2 插件。</p><table tabindex="0"><thead><tr><th>组合</th><th>结果</th></tr></thead><tbody><tr><td>新主程序 + API v2 插件</td><td>保持兼容</td></tr><tr><td>新主程序 + Paddle OCR 0.8.0</td><td>使用 API v3 作业协议</td></tr><tr><td>旧主程序 + Paddle OCR 0.8.0</td><td>启动健康检查失败，不启用</td></tr><tr><td>新主程序 + 未知更高 API</td><td>标记损坏，不启用</td></tr></tbody></table><p>API v3 插件必须校验宿主运行时注入的 <code>hostContext</code>：常驻 Sidecar 在首次启动方法中校验，一次性 Sidecar 在每次请求顶层校验。该信息不得来自 manifest。</p><h2 id="_2-已落地契约" tabindex="-1">2. 已落地契约 <a class="header-anchor" href="#_2-已落地契约" aria-label="Permalink to &quot;2. 已落地契约&quot;">​</a></h2><h3 id="_2-1-稳定贡献点" tabindex="-1">2.1 稳定贡献点 <a class="header-anchor" href="#_2-1-稳定贡献点" aria-label="Permalink to &quot;2.1 稳定贡献点&quot;">​</a></h3><p>OCR 配置只持久化稳定事实：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PluginOcrEngineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  pluginId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  contributionId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  modelProfile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  language</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>name</code>、<code>method</code> 和 capabilities 每次从当前 manifest 解析。找不到显式 <code>contributionId</code> 时直接失败，不按方法名回退。旧配置仅在已知映射、唯一方法或唯一 OCR contribution 时自动迁移；有歧义时要求用户重新选择。Smart OCR、实时字幕和窗口自动化共用该迁移器。</p><h3 id="_2-2-作业生命周期" tabindex="-1">2.2 作业生命周期 <a class="header-anchor" href="#_2-2-作业生命周期" aria-label="Permalink to &quot;2.2 作业生命周期&quot;">​</a></h3><ol><li>宿主生成不可复用的 <code>jobId</code> 并先订阅事件。</li><li>插件提交方法立即返回 <code>{ accepted: true, jobId }</code>。</li><li>插件 FIFO 分批执行，并通过 progress event 推送合法进度和局部结果。</li><li>completion、failure 或 cancelled event 产生唯一终态。</li><li>取消通过 manifest 声明的 <code>cancelMethod</code> 执行；宿主等待取消终态后清理临时资源。</li><li>超时按“无合法进度时长”计算，每次合法进度刷新计时。</li></ol><p><code>maxBatchSize</code> 是插件运行时能力描述，不授权宿主二次分片。job 模式必须声明流式结果和常驻事件通道。</p><h3 id="_2-3-进程代际" tabindex="-1">2.3 进程代际 <a class="header-anchor" href="#_2-3-进程代际" aria-label="Permalink to &quot;2.3 进程代际&quot;">​</a></h3><ul><li>每次常驻进程启动生成 <code>generationId</code>，pending map 与 stdout reader 绑定同一代际。</li><li>插入、完成和超时清理只访问所属代际；前端忽略旧代际事件。</li><li>强制终止后等待子进程退出，再启动同 <code>pluginId</code> 新进程。</li><li>Broker 转发同时校验源、目标 generation；等待 I/O 时不持有全局进程表锁。</li><li>旧代际不得转发、回写或完成新代际请求。</li></ul><h2 id="_3-paddle-ocr-运行模型" tabindex="-1">3. Paddle OCR 运行模型 <a class="header-anchor" href="#_3-paddle-ocr-运行模型" aria-label="Permalink to &quot;3. Paddle OCR 运行模型&quot;">​</a></h2><ul><li>协调线程持续读取 stdin，可及时处理提交、取消、健康检查和关闭。</li><li>单一 OCR worker 独占 <code>EngineHolder</code>，按 FIFO 执行，并在内部批次前后检查取消令牌。</li><li>作业表保存 <code>jobId -&gt; cancellation token</code>，拒绝重复 ID。</li><li>协议输出与 <code>NativeStdoutSilencer</code> 共用 stdout 锁，避免原生输出抑制吞掉 JSONL。</li><li>单图识别错误保留在正常完成结果；模型加载、队列和协议错误才产生失败终态。</li></ul><h2 id="_4-已合并的-review-处理结果" tabindex="-1">4. 已合并的 review 处理结果 <a class="header-anchor" href="#_4-已合并的-review-处理结果" aria-label="Permalink to &quot;4. 已合并的 review 处理结果&quot;">​</a></h2><p>原 review 跟进已合并到本文，以下问题均已关闭：</p><ul><li>排队取消立即产生唯一终态；单作业取消超时不再重启共享 Sidecar 误伤其他作业。</li><li>消除提交前 AbortSignal 竞态，所有退出路径清理计时器。</li><li>Paddle OCR UI 按合法进度刷新超时，不使用任务总时长超时。</li><li><code>hard-subtitle-extractor</code> 使用稳定 <code>contributionId</code>；AHK Automator 使用宿主 OCR facade 和 <code>ServiceResult</code>。</li><li>旧 OCR 配置与历史记录兼容展示；歧义配置显式降级为待选择。</li><li>manifest job capability、<code>hostContext</code> 和 Broker 双代际均有运行时校验。</li><li>标准 OCR 结果保留可选行框，满足点击定位等结构化消费。</li><li>Native / Sidecar 开发产物统一部署到 <code>dev-bin/&lt;platform&gt;/</code>；manifest 不再依赖 Cargo <code>target/</code> 缓存布局。</li><li>插件不可用状态保留结构化诊断，不覆盖协议、握手、产物或兼容性原始原因。</li></ul><p>“通用 Sidecar 作业客户端”不再作为本轮未完成项：当前状态机先收敛在 OCR 平台，出现第二个 job contribution 后再单独评估抽取。</p><h2 id="_5-当前唯一剩余门禁" tabindex="-1">5. 当前唯一剩余门禁 <a class="header-anchor" href="#_5-当前唯一剩余门禁" aria-label="Permalink to &quot;5. 当前唯一剩余门禁&quot;">​</a></h2><ul><li>[ ] 使用主应用与 Paddle OCR 发布候选产物，在真实 Tauri WebView 完成选择、分批进度、局部结果、取消、无进度超时恢复、失败恢复、多窗口事件和进程重启后的首次调用。</li><li>[ ] 核对主应用、插件版本、API version、最低宿主版本和 manifest 当前平台产物路径。</li><li>[ ] 主应用与依赖 API v3 的插件安排在同一发布窗口；不得仅凭开发态成功调用宣称发布验收完成。</li></ul><p>2026-07-25 曾因开发 manifest 指向错误的 target-triple 缓存而启动旧 API v2 二进制；构建链已统一到稳定 <code>dev-bin/&lt;platform&gt;/</code>。2026-07-27 已确认开发模式实际调用 API v3 并使用新的分批优化。</p><h2 id="_6-非目标" tabindex="-1">6. 非目标 <a class="header-anchor" href="#_6-非目标" aria-label="Permalink to &quot;6. 非目标&quot;">​</a></h2><ul><li>不删除 API v2 插件加载能力。</li><li>不猜测有多个候选项的旧配置。</li><li>不自动重试已经开始执行的 OCR 作业，避免重复副作用。</li><li>不在本阶段把全部 Sidecar 通信迁移到命名管道；JSON Lines 仍是传输层。</li></ul><h2 id="_7-完成口径" tabindex="-1">7. 完成口径 <a class="header-anchor" href="#_7-完成口径" aria-label="Permalink to &quot;7. 完成口径&quot;">​</a></h2><p>联合验收矩阵通过并同步发布安排明确后，删除本文；稳定 API 契约继续由插件开发指南、宿主源码和插件自身文档维护。</p>`,29)])])}const u=a(s,[["render",d]]);export{k as __pageData,u as default};
